using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: GetTypeInfo returns JsonTypeInfo,
//    which is safely down-castable to JsonTypeInfo<T>.
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");

// 2) Probe without throwing using TryGetTypeInfo (added in .NET 9).
//    Returns false instead of throwing if metadata isn't resolvable.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    var typed = (JsonTypeInfo<Person>)info!;
    Console.WriteLine($"\nTryGetTypeInfo succeeded for Person (properties: {typed.Properties.Count})");
}

// Demonstrate the "not available" branch — use a resolver that handles nothing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty composite = resolves nothing
};

if (limited.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("\nUnexpectedly found metadata");
else
    Console.WriteLine("\nTryGetTypeInfo correctly returned false — no metadata for Person");

public record Person(string Name, int Age);

